<template>
    <view class="page-root">
        <!-- WebView 文件选择器 - 打开系统原生文件选择器访问本地文件 -->
        <web-view
            v-if="webviewUrl"
            :src="webviewUrl"
            @message="handleMessage"
            @error="handleError"
            @load="handleLoad">
        </web-view>
        <!-- 加载中占位 -->
        <view v-else class="loading-container">
            <view class="loading-spinner"></view>
            <text class="loading-text">正在加载文件选择器...</text>
        </view>
    </view>
</template>

<script>
// CloudBase 静态托管域名（需在微信后台将此域名加入业务域名白名单）
var FILE_PICKER_URL = 'https://cloud1-d2g6k45v21dd52696-1441744670.tcloudbaseapp.com/file-picker.html';

export default {
    data() {
        return {
            webviewUrl: FILE_PICKER_URL,
            messageReceived: false
        };
    },
    methods: {
        /**
         * 处理 WebView 通过 wx.miniProgram.postMessage 发来的消息
         */
        handleMessage(e) {
            var messages = e.detail.data;
            if (!messages || messages.length === 0) return;

            var lastMsg = messages[messages.length - 1];
            if (!lastMsg) return;

            // 返回请求：优先级最高，不受 messageReceived 限制
            if (lastMsg.type === 'go-back') {
                uni.navigateBack();
                return;
            }

            // 文件数据：防止重复处理
            if (this.messageReceived) return;
            if (lastMsg.type !== 'file-selected' || !lastMsg.fileData) return;

            this.messageReceived = true;
            this.saveReceivedFile(lastMsg);
        },

        /**
         * 将 WebView 传来的 base64 数据写入小程序临时文件
         * 使用 writeFileSync 确保在页面卸载前数据完全写入
         */
        saveReceivedFile(fileMsg) {
            try {
                var fs = wx.getFileSystemManager();

                // 防止文件名冲突，添加时间戳前缀
                var safeName = Date.now() + '_' + fileMsg.fileName;
                var tempFilePath = wx.env.USER_DATA_PATH + '/' + safeName;

                // 同步写入确保数据完整性（页面卸载前必须完成）
                fs.writeFileSync(
                    tempFilePath,
                    wx.base64ToArrayBuffer(fileMsg.fileData),
                    'binary'
                );

                console.log('文件已写入:', tempFilePath);

                // 存入全局数据供 upload-price 页面使用
                var app = getApp();
                if (!app.globalData) app.globalData = {};
                app.globalData.pickedFile = {
                    path: tempFilePath,
                    name: fileMsg.fileName,
                    size: fileMsg.fileSize
                };
            } catch (err) {
                console.error('写入文件失败:', err);
                // 失败时清理
                var app = getApp();
                if (app.globalData) app.globalData.pickedFile = null;
            }
        },

        onUnload() {
            if (!this.messageReceived) {
                console.log('文件选择器已关闭（未选择文件）');
            }
        },

        handleLoad(e) {
            console.log('WebView 加载完成');
        },

        handleError(e) {
            var errMsg = (e.detail && e.detail.errMsg) || '';
            console.error('WebView 事件:', errMsg);

            // 只有「域名不在白名单」才自动返回，其他情况用户可自行操作
            if (errMsg.indexOf('not in domain list') !== -1) {
                uni.showToast({
                    title: '域名未配置白名单，请去微信后台添加',
                    icon: 'none',
                    duration: 3000
                });
                setTimeout(function() {
                    uni.navigateBack();
                }, 2000);
            }
        }
    }
};
</script>

<style>
.page-root {
    width: 100%;
    height: 100vh;
    position: relative;
}

web-view {
    width: 100%;
    height: 100%;
}

.loading-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100vh;
    background: linear-gradient(135deg, #0d1526 0%, #1e293b 100%);
}

.loading-spinner {
    width: 48rpx;
    height: 48rpx;
    border: 4rpx solid rgba(200, 170, 110, 0.3);
    border-top-color: #c8aa6e;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin-bottom: 24rpx;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

.loading-text {
    font-size: 28rpx;
    color: rgba(255, 255, 255, 0.6);
}
</style>
